import { Component, OnInit } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { AccountService } from '../../../../data/service/auth/account.service';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { Urls } from '../../../../core/common/Urls';
import { ConfirmEmailModel } from '../../../../data/model/account/ResetPasswordModel';

@Component({
  selector: 'app-confirm-email',
  templateUrl: './confirm-email.component.html',
  styleUrls: ['./confirm-email.component.scss']
})
export class ConfirmEmailComponent implements OnInit {

  success = 0;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
    private accountService: AccountService,
    public toastController: ToastController,
    public loadingController: LoadingController
  ) {
  }

  ngOnInit(): void {

    this.activatedRoute.queryParams.subscribe(queryParams => {

      const id = queryParams.id;
      const email = queryParams.email;

      if (id === undefined || email === undefined || email === '' || id === '') {

        this.router.navigateByUrl(Urls.HomeUrl);
        return;

      } else {

        SharedIonic.loading(this.loadingController);

        this.accountService.ConfirmEmail(new ConfirmEmailModel(
          id, email
        )).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'با موفقیت انجام شد');
            this.success = 1;
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
            this.success = 2;
          }
        );
      }
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

}
